"""Regenerates src/text/cp932_table.inc from Python's cp932 codec (run from the repository root)."""
lead = list(range(0x81, 0xA0)) + list(range(0xE0, 0xFD))
rows = []
for l in lead:
    row = []
    for t in range(0x40, 0xFD):
        try:
            s = bytes([l, t]).decode("cp932") if t != 0x7F else ""
            row.append(ord(s) if len(s) == 1 else 0)
        except UnicodeDecodeError:
            row.append(0)
    rows.append(row)
out = [
    "// Generated by tools/gen_cp932.py: Windows code page 932 double-byte characters -> UTF-16 code units",
    "// (0 = undefined). Rows are lead bytes 0x81..0x9F then 0xE0..0xFC, columns trail bytes 0x40..0xFC.",
    "static constexpr unsigned short kCp932Table[%d][%d] = {" % (len(lead), 0xFD - 0x40),
]
out += ["  {" + ",".join("0x%04X" % v for v in row) + "}," for row in rows]
out.append("};")
open("src/text/cp932_table.inc", "w").write("\n".join(out) + "\n")
